import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"43 - Telegram Bot","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/43-telegram-bot-configuration.md","filePath":"developers/design-documentation/43-telegram-bot-configuration.md"}'),d={name:"developers/design-documentation/43-telegram-bot-configuration.md"};function i(n,e,s,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_43-telegram-bot" tabindex="-1">43 - Telegram Bot <a class="header-anchor" href="#_43-telegram-bot" aria-label="Permalink to &quot;43 - Telegram Bot&quot;">​</a></h1><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>blueprints/telegram.py</code></td><td>Session-authenticated React UI APIs for config, lifecycle, users, analytics, explicit sends. Blueprint <code>telegram_bp</code>, <code>url_prefix=&quot;/telegram&quot;</code></td></tr><tr><td><code>restx_api/telegram_bot.py</code></td><td>API-key REST management and direct notification resources</td></tr><tr><td><code>services/telegram_bot_service.py</code></td><td>Bot initialization, polling, commands, lifecycle</td></tr><tr><td><code>services/telegram_alert_service.py</code></td><td>Synchronous HTTP delivery, async executor, retry queue, formatting</td></tr><tr><td><code>database/telegram_db.py</code></td><td>Encrypted config, linked users, preferences, notifications/stats. Models <code>TelegramUser</code> (<code>telegram_users</code>), <code>BotConfig</code> (<code>bot_config</code>), <code>CommandLog</code> (<code>command_logs</code>), <code>NotificationQueue</code> (<code>notification_queue</code>), <code>UserPreference</code> (<code>user_preferences</code>)</td></tr><tr><td><code>subscribers/telegram_subscriber.py</code></td><td>EventBus-to-alert mapping</td></tr></tbody></table><p>The React pages live under <code>frontend/src/pages/telegram/</code> and use <code>frontend/src/api/telegram.ts</code>.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>The bot configuration persists an encrypted token, polling/webhook settings, and <code>is_active</code>. Start initializes the bot and starts polling when configured. Stop updates the persisted active state and stops the service.</p><p><code>is_active</code> is the source of truth for automatic-alert gating. Order-event alerts and Flow Telegram nodes skip delivery when the bot is stopped. Explicit UI test/send/broadcast actions and <code>/api/v1/telegram/notify</code> intentionally bypass this gate because they are direct human/API requests.</p><h2 id="eventbus-alerts" tabindex="-1">EventBus Alerts <a class="header-anchor" href="#eventbus-alerts" aria-label="Permalink to &quot;EventBus Alerts&quot;">​</a></h2><p>Successful order-related topics are mapped through <code>telegram_subscriber.py</code> to <code>send_order_alert()</code>. Failure events and analyzer errors are deliberately not sent to chat. Batch operations produce one summary event, avoiding one notification per child order.</p><p>Alerts resolve the local username from the API key, verify that a Telegram user is linked and notifications are enabled, then enqueue delivery on the shared five-worker alert executor.</p><h2 id="explicit-delivery" tabindex="-1">Explicit Delivery <a class="header-anchor" href="#explicit-delivery" aria-label="Permalink to &quot;Explicit Delivery&quot;">​</a></h2><p><code>send_alert_sync()</code> calls Telegram&#39;s HTTP API through <code>httpx</code>. It supports Markdown formatting fallback to plain text and queues failed/timeout deliveries in the notification store. The REST notify endpoint can use fire-and-forget or wait for one immediate delivery attempt.</p><h2 id="restx-surface-and-limitations" tabindex="-1">RESTX Surface And Limitations <a class="header-anchor" href="#restx-surface-and-limitations" aria-label="Permalink to &quot;RESTX Surface And Limitations&quot;">​</a></h2><p>The <code>/api/v1/telegram</code> namespace registers config GET/POST, start, stop, webhook, users, broadcast, notify, stats, and preferences GET/POST.</p><p>Current limitations must remain explicit:</p><ul><li>The REST webhook validates <code>X-Telegram-Bot-Api-Secret-Token</code> and acknowledges valid updates, but its command dispatch call is not implemented.</li><li>The REST broadcast handler validates input/config but currently returns zero successful and zero failed deliveries.</li><li>These limitations do not apply to the session-authenticated blueprint broadcast path, which iterates linked users and attempts delivery.</li></ul><h2 id="webhook-security" tabindex="-1">Webhook Security <a class="header-anchor" href="#webhook-security" aria-label="Permalink to &quot;Webhook Security&quot;">​</a></h2><p>The expected secret comes from <code>TELEGRAM_WEBHOOK_SECRET</code>; if absent, <code>get_webhook_secret()</code> derives a fallback from the stored bot token as the first 32 characters of its SHA-256 digest. Missing and incorrect headers return 401 and 403. Payloads must be objects containing <code>update_id</code>, otherwise the handler returns 400. When neither the environment variable nor a bot token is configured, no secret can be resolved and the handler currently skips header verification instead of rejecting the request.</p><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>REST Telegram calls normally use <code>TELEGRAM_RATE_LIMIT</code> (default <code>&quot;30 per minute&quot;</code>, read in <code>restx_api/telegram_bot.py</code>). REST broadcast uses a hard-coded <code>&quot;5 per minute&quot;</code>.</p><p>On the session-authenticated blueprint, <code>TELEGRAM_MESSAGE_RATE_LIMIT</code> (default <code>&quot;10 per minute&quot;</code>, read in <code>blueprints/telegram.py</code>) is applied to <code>/telegram/send-message</code> only. The other blueprint routes carry no <code>@limiter.limit</code> decorator.</p><p>Neither <code>TELEGRAM_RATE_LIMIT</code> nor <code>TELEGRAM_MESSAGE_RATE_LIMIT</code> nor <code>TELEGRAM_WEBHOOK_SECRET</code> appears in <code>.sample.env</code>; each falls back to the default written in code.</p><p>Telegram&#39;s upstream limits and transient errors are handled separately by delivery/retry behavior.</p><h2 id="commands-and-charts" tabindex="-1">Commands And Charts <a class="header-anchor" href="#commands-and-charts" aria-label="Permalink to &quot;Commands And Charts&quot;">​</a></h2><p>Bot commands query normalized order/account data, control supported automation actions, and can render charts using Plotly/Kaleido. Chart rendering requires the Chromium/Kaleido runtime verified by Docker CI. The exact command registry belongs to <code>telegram_bot_service.py</code>, not a copied static list in this architecture page.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>blueprints/telegram.py</code></td><td>Authenticated web management</td></tr><tr><td><code>restx_api/telegram_bot.py</code></td><td>External REST resources</td></tr><tr><td><code>services/telegram_bot_service.py</code></td><td>Command and bot lifecycle</td></tr><tr><td><code>services/telegram_alert_service.py</code></td><td>Delivery and gating</td></tr><tr><td><code>database/telegram_db.py</code></td><td>Persistent state</td></tr><tr><td><code>frontend/src/pages/telegram/TelegramConfig.tsx</code></td><td>React configuration page</td></tr></tbody></table>',27)])])}const m=t(d,[["render",i]]);export{p as __pageData,m as default};
